// Para cada lead, extrae subscriber_id del session_id (formato 'wa_XXXX', 'ig_XXXX', etc.)
// y prepara el contexto para el LLM.
// v1.1: arma 'instrucciones_tono' por toque de forma determinista — el LLM solo redacta,
// no decide entre 2 reglas (eso causaba mensajes idénticos en toque 1 y 2).
const lead = $input.first().json;
const sessionId = String(lead.session_id || '');
const parts = sessionId.split('_');
const canal = parts[0] || 'unknown';
const subscriberId = parts.slice(1).join('_') || '';

const datos = lead.datos_capturados || {};
const nombre = datos.nombre || '';
const equipo = datos.equipo || datos.equipo_o_aplicacion || '';
const toque = Number(lead.toque_a_enviar);

// Instrucciones específicas por toque — el LLM las usa directamente, no elige.
let instrucciones_tono = '';
if (toque === 1) {
  instrucciones_tono = `Este es el PRIMER seguimiento, 24h después de la última interacción. Reactivá la conversación con calidez en 2 partes naturales (parte1 = saludo + apertura cálida; parte2 = referencia a la consulta previa + UNA pregunta abierta para invitar a retomar tipo "¿pudiste verlo?", "¿seguís interesado?", "¿necesitás algo más para decidir?"). NO uses despedida tipo "saludos" — es pregunta, no cierre. NO menciones que es un seguimiento ni que pasaron horas/días. Dejá parte3 vacía.`;
} else if (toque === 2) {
  instrucciones_tono = `Este es el SEGUNDO y ÚLTIMO seguimiento, 7 días después del primero sin respuesta. Tono de cierre amable en 2 partes (parte1 = saludo + aviso explícito de que es el último mensaje desde el asistente, frase tipo "este es mi último mensaje desde acá" o "no te escribo más desde el bot"; parte2 = invitación a que retome cuando quiera + saludo de cierre tipo "saludos"). NO hagas preguntas — es cierre, no invitación a responder. Dejá parte3 vacía.`;
} else {
  instrucciones_tono = 'Mensaje genérico de reactivación en 1 parte (solo parte1). Tono cálido y abierto. Dejá parte2 y parte3 vacías.';
}

return [{
  json: {
    session_id: sessionId,
    subscriber_id: subscriberId,
    canal,
    nombre,
    equipo,
    toque,
    instrucciones_tono,
    seguimientos_enviados: lead.seguimientos_enviados,
    datos_capturados: datos,
    ultima_actividad: lead.ultima_actividad
  }
}];

// v1.1 multi-parte: parsea el JSON {parte1, parte2, parte3} del LLM y compacta
// partes no-vacías en ai_msg_1/2/3 + ai_msg_count, mismo patrón que el main 'Split Respuesta'.
const llmOut = $input.first().json;
const leadCtx = $('Prepare lead context').item.json;

// El LLM con jsonOutput=true puede devolver el JSON en .message.content (string) o ya parseado.
const raw = llmOut.message?.content ?? llmOut.content ?? llmOut;
let parsed = {};
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : (raw && typeof raw === 'object' ? raw : {});
} catch (e) {
  // Fallback: si el LLM rompió el JSON, mete todo en parte1.
  parsed = { parte1: typeof raw === 'string' ? raw : String(raw), parte2: '', parte3: '' };
}

// Compactar partes no-vacías en orden (descarta empties intermedios, evita que ManyChat saltee mensaje).
const allParts = [parsed.parte1, parsed.parte2, parsed.parte3]
                   .map(p => String(p || '').trim())
                   .filter(p => p.length > 0);

const ai_msg_1 = allParts[0] || '';
const ai_msg_2 = allParts[1] || '';
const ai_msg_3 = allParts[2] || '';
const ai_msg_count = allParts.length || 1;

return [{
  json: {
    ...leadCtx,
    ai_msg_1,
    ai_msg_2,
    ai_msg_3,
    ai_msg_count
  }
}];

